batterySource:
// generic-rag-chunking P-012 R-37 live battery: the peers-know archive lookup (the
// working-tree peersKnowLookup behind coord:orient's peersKnow fold, called exactly as
// orient.ts calls it: buildQueryEmbedderResolved + resolveProseProfileSelection) against
// the live operator DB after the consult_questions chunk sync + embed.
//
// Sample: N settled consult questions (closed_answered, not an archive copy, with a
// string outcome.answer) in the workspace whose question is over 3,500 characters and
// has embedded chunks, in md5(conversation_id) order (fixed pseudo-random, no
// hand-picking). Query: one sentence from the part past the first 2,000 characters
// that the 8 capped windows still cover, whose opening words do not occur in the first
// 2,000 characters.
//
// The site's default result count is 1 (top hit above DEFAULT_ARCHIVE_FLOOR). Each row
// records: the default call's ref (R-37's verdict), the same call with floor 0 (so a
// ranking miss can be told apart from a floor miss), the target's best chunk cosine,
// and its rank + cosine by its own parent vector alone.
export {};
const base = 'file://~/papercupai-workspace/papercusp/packages/operator-core/lib/';
const { installSearchDefaults } = await import(base + 'search/configure-search-defaults.ts');
const { buildQueryEmbedderResolved } = await import(base + 'agent-tools/search/embedder.ts');
const { resolveProseProfileSelection } = await import(base + 'search/prose-vector-dims.ts');
const { CONSULT_QUESTIONS_CHUNK_SURFACE } = await import(base + 'search/chunks/registry.ts');
const { peersKnowLookup } = await import(base + 'consult/peers-know.ts');
const { DEFAULT_ARCHIVE_FLOOR } = await import(base + 'consult/get-feedback-core.ts');
const { getOrgPg } = await import('@papercusp/db-org');
installSearchDefaults();

const CUT = 2000;
const N = Number(process.env.N ?? 10);
const WS = 'papercusp-workspace';
const sp = CONSULT_QUESTIONS_CHUNK_SURFACE.splitter as { size: number; overlap: number };
const covered = sp.size + (CONSULT_QUESTIONS_CHUNK_SURFACE.maxChunks! - 1) * (sp.size - sp.overlap);
const resolved = await buildQueryEmbedderResolved({ acquireBudgetMs: 20_000 });
if (!resolved) throw new Error('no query embedder');
const profile = resolveProseProfileSelection(resolved.mode, resolved.profile);
if (!profile) throw new Error(`no prose profile for ${resolved.mode}`);
const { sql } = getOrgPg();
console.log('SETUP', JSON.stringify({ mode: resolved.mode, floor: DEFAULT_ARCHIVE_FLOOR, margin: CONSULT_QUESTIONS_CHUNK_SURFACE.chunkMargin, covered }));

const items = await sql.unsafe<Array<{ id: string; text: string }>>(
  `SELECT c.conversation_id AS id, c.question AS text
     FROM harness_shared.consult_state c
    WHERE c.workspace_id = $1 AND c.state = 'closed_answered'
      AND (c.outcome->>'source') IS DISTINCT FROM 'archive'
      AND jsonb_typeof(c.outcome->'answer') = 'string'
      AND c.query_embedding IS NOT NULL
      AND length(c.question) > 3500
      AND EXISTS (SELECT 1 FROM harness_shared.text_chunks t
                   WHERE t.surface = 'consult_questions' AND t.parent_key = ARRAY[c.workspace_id, c.conversation_id]
                     AND t.embedding IS NOT NULL)
    ORDER BY md5(c.conversation_id) LIMIT $2`,
  [WS, N * 3],
);
console.log('POPULATION', JSON.stringify({ candidates: items.length }));

const rows: Array<Record<string, unknown>> = [];
for (const t of items) {
  if (rows.filter((r) => !r.skipped).length >= N) break;
  const head = t.text.slice(0, CUT).toLowerCase();
  const region = t.text.slice(CUT, Math.min(t.text.length, covered) - 50);
  const sentences = region
    .split(/(?<=[.!?])\s+|\n+/)
    .map((s) => s.replace(/[`*_#>|[\]()]/g, ' ').replace(/\s+/g, ' ').trim())
    .filter((s) => s.split(' ').length >= 8 && s.length <= 220 && !head.includes(s.toLowerCase().slice(0, 40)));
  // QUERY_MODE=passage: a verbatim ~PASSAGE_CHARS slice from the middle of the covered
  // tail, starting at a word boundary, whose opening 40 characters are absent from the head.
  const passage = (() => {
    const len = Number(process.env.PASSAGE_CHARS ?? 600);
    let start = Math.floor(Math.max(0, region.length - len) / 2);
    while (start < region.length && !/\s/.test(region[start]!)) start++;
    const p = region.slice(start, start + len).replace(/\s+/g, ' ').trim();
    return p.length >= len * 0.8 && !head.includes(p.toLowerCase().slice(0, 40)) ? p : undefined;
  })();
  const query = process.env.QUERY_MODE === 'passage' ? passage : sentences[Math.floor(sentences.length * 0.6)];
  if (!query) {
    rows.push({ item: t.id, skipped: 'no usable sentence' });
    continue;
  }
  const qv = await resolved.embed(query);
  const vec = `[${qv.join(',')}]`;
  const [own] = await sql.unsafe<Array<{ rank: number; sim: number }>>(
    `WITH r AS (SELECT conversation_id, 1 - (query_embedding <=> $2::vector) AS sim,
                       row_number() OVER (ORDER BY query_embedding <=> $2::vector) AS rank
                  FROM harness_shared.consult_state
                 WHERE workspace_id = $1 AND state = 'closed_answered' AND query_embedding IS NOT NULL
                   AND (outcome->>'source') IS DISTINCT FROM 'archive')
     SELECT rank::int, sim::float8 AS sim FROM r WHERE conversation_id = $3`,
    [WS, vec, t.id],
  );
  const [chunk] = await sql.unsafe<Array<{ sim: number }>>(
    `SELECT max(1 - (embedding <=> $1::vector))::float8 AS sim FROM harness_shared.text_chunks
      WHERE surface = 'consult_questions' AND parent_key = ARRAY[$2, $3] AND embedding IS NOT NULL`,
    [vec, WS, t.id],
  );
  const q = { embed: async () => qv, profile };
  const dflt = await peersKnowLookup(sql, q, { workspaceId: WS, intent: query });
  const open = await peersKnowLookup(sql, q, { workspaceId: WS, intent: query, floor: 0 });
  rows.push({
    item: t.id,
    chars: t.text.length,
    queryOffset: t.text.indexOf(query.split(' ').slice(0, 4).join(' ')),
    query,
    returned: dflt?.ref === t.id,
    defaultRef: dflt?.ref ?? null,
    defaultSim: dflt?.sim ?? null,
    rankedFirstNoFloor: open?.ref === t.id,
    noFloorRef: open?.ref ?? null,
    noFloorSim: open?.sim ?? null,
    bestChunkSim: chunk?.sim ?? null,
    ownVectorRank: own?.rank ?? null,
    ownVectorSim: own?.sim ?? null,
  });
}
for (const r of rows) console.log('ROW', JSON.stringify(r));
const done = rows.filter((r) => !r.skipped);
console.log(
  'SUMMARY',
  JSON.stringify({
    at: new Date().toISOString(),
    n: done.length,
    returned: done.filter((r) => r.returned).length,
    rankedFirstNoFloor: done.filter((r) => r.rankedFirstNoFloor).length,
    ownVectorFirst: done.filter((r) => r.ownVectorRank === 1).length,
    chunkOverFloorAfterMargin: done.filter(
      (r) => typeof r.bestChunkSim === 'number' && (r.bestChunkSim as number) - (CONSULT_QUESTIONS_CHUNK_SURFACE.chunkMargin ?? 0) >= DEFAULT_ARCHIVE_FLOOR,
    ).length,
  }),
);
process.exit(0);
